package org.maale.bible.ingest;
import static org.junit.jupiter.api.Assertions.*; import java.nio.file.*; import java.util.zip.*; import java.io.*; import org.junit.jupiter.api.Test;
class ArchiveSafetyValidatorTest {
 private ArchiveSafetyValidator.Limits limits(){return new ArchiveSafetyValidator.Limits(10,10000,10000,100);}
 @Test void extractsVerifiedSyntheticZip() throws Exception {Path d=Files.createTempDirectory("zip");Path z=d.resolve("a.zip");try(ZipOutputStream o=new ZipOutputStream(Files.newOutputStream(z))){o.putNextEntry(new ZipEntry("GEN.usfm"));o.write("\\id GEN Synthetic".getBytes());o.closeEntry();}Path out=d.resolve("out");ArchiveSafetyValidator.extractVerified(z,Sha256Verifier.sha256(z),out,limits());assertTrue(Files.exists(out.resolve("GEN.usfm")));}
 @Test void rejectsWrongArchiveDigestBeforeExtraction() throws Exception {Path d=Files.createTempDirectory("zip");Path z=d.resolve("a.zip");Files.write(z,new byte[]{1});assertThrows(IOException.class,()->ArchiveSafetyValidator.extractVerified(z,"0".repeat(64),d.resolve("out"),limits()));assertFalse(Files.exists(d.resolve("out")));}
 @Test void rejectsTraversalAndCleansStaging() throws Exception {Path d=Files.createTempDirectory("zip");Path z=d.resolve("bad.zip");try(ZipOutputStream o=new ZipOutputStream(Files.newOutputStream(z))){o.putNextEntry(new ZipEntry("../escape.txt"));o.write(1);o.closeEntry();}Path out=d.resolve("out");assertThrows(IOException.class,()->ArchiveSafetyValidator.extractVerified(z,Sha256Verifier.sha256(z),out,limits()));assertFalse(Files.exists(d.resolve("escape.txt")));assertFalse(Files.exists(out));}
 @Test void rejectsExpandedSizeLimit() throws Exception {Path d=Files.createTempDirectory("zip");Path z=d.resolve("large.zip");try(ZipOutputStream o=new ZipOutputStream(Files.newOutputStream(z))){o.putNextEntry(new ZipEntry("large.txt"));o.write(new byte[500]);o.closeEntry();}var small=new ArchiveSafetyValidator.Limits(10,100,1000,100);assertThrows(IOException.class,()->ArchiveSafetyValidator.extractVerified(z,Sha256Verifier.sha256(z),d.resolve("out"),small));}
}